// The built-in blocker in the service worker (docs/adblock.md): the engine
// of rust/block (Brave's adblock crate) instantiated from the module the
// controller handed this thread with the other wasm modules
// (src/wasm/thread.ts), fed the lists the host named, and asked before every
// request goes to the transport. The lists are fetched through the transport
// (the user's own address never reaches the list servers), compiled once and
// kept serialized in CacheStorage under a key of the list URLs and the
// engine's format, so a restarted worker loads in milliseconds (measured:
// 9 ms for the 198,000-line Brave list, against 245 ms to compile it) and
// the lists are fetched again only when the stored engine is older than the
// refresh interval. A fetch that fails leaves the stored engine serving;
// with nothing stored, the blocker is off until a fetch succeeds.
//
// The crate never discards a compiled regex on wasm (it has no clock), so a
// long-lived worker's instance only grows: past a ceiling it is replaced by
// a fresh one loading the same serialized engine.
import type { EngineList } from '../blocker/build';
import { carriedCsp, withWorkerSource } from '../blocker/csp';
import {
	BlockerInstance,
	FLAG_HOSTS,
	FLAG_TRUSTED,
	OP,
} from '../blocker/instance';
import {
	requestTypeOf,
	type AdblockInit,
	type AdblockList,
	type AdblockPage,
} from '../blocker/types';
import type { RewritePool } from './rewritePool';
import type Router from './Router';

/** the CacheStorage store the serialized engines and the resources live in */
const STORE = 'stomp-adblock';
/** the engine's serialized format: the crate's version, which must match to load (Engine::deserialize) */
const FORMAT = 'adblock-rust-0.13.5-dat8';
const STORED_AT = 'x-stomp-stored-at';
/** linear memory past which the instance is replaced */
const MEMORY_LIMIT = 160 * 1024 * 1024;
/**
 * how long a navigation waits for an engine that is being built for the
 * first time (the lists are being fetched): past it the document loads
 * unfiltered rather than not at all, and the engine serves once it is built
 */
const FIRST_BUILD_WAIT_MS = 5_000;
/** scriptlet rewrites kept, by their lines (a site's pages share theirs) */
const SCRIPT_MEMO = 64;
/**
 * how long after this worker's first navigation is answered a start's list
 * downloads begin: the page's first requests for its subresources go out
 * in that time, and their names reach the wisp server's resolver before the
 * lists' hosts
 */
const LIST_AFTER_MS = 250;
/** how long a start's list downloads wait for a first navigation at the most */
const LIST_WAIT_MS = 2_000;

/**
 * The blocker module's bytes, as the newest handshake handed them
 * (heardBlockerBytes): a rewrite worker that compiles an engine
 * compiles the module from them, as a compiled module cannot be posted from
 * a service worker
 */
let moduleBytes: ArrayBuffer | undefined;

/** the modules a handshake (or a later message of its controller) handed this thread */
export function heardBlockerBytes(modules?: Record<string, unknown>) {
	const bytes = modules?.blocker;
	if (bytes instanceof ArrayBuffer) moduleBytes = bytes;
}

let navigationAnswered: () => void;
const firstNavigation = new Promise<void>((resolve) => {
	navigationAnswered = resolve;
});
let navigated = false;

/**
 * This worker's first navigation went to the transport (src/server/rewrites.ts).
 * A start's list downloads wait for it (listTurn): the transport opens a
 * connection to each list's host, and the wisp server resolves the names of
 * a burst of connections on a few threads (four on holyWisp), so a page asked
 * for in the same moment waited behind 6 to 8 lookups for its own (43 to 95
 * ms, 3 s and more when a lookup stalled).
 */
export function navigationUpstream(answer: Promise<unknown>) {
	if (navigated) return;
	navigated = true;
	answer
		.catch(() => {})
		.then(() => setTimeout(navigationAnswered, LIST_AFTER_MS));
}

/** the host a list is downloaded from, as the transport connects to it */
function listHost(url: string): string {
	try {
		const { protocol, host } = new URL(url, globalThis.location?.href);
		return `${protocol}//${host}`;
	} catch (error) {
		return url;
	}
}

/** a start's list downloads may begin (navigationUpstream) */
function listTurn(): Promise<void> {
	return Promise.race([
		firstNavigation,
		new Promise<void>((resolve) => setTimeout(resolve, LIST_WAIT_MS)),
	]);
}
/** a blocker that is on by default and cannot be had says so once a thread */
let saidOff = false;

export interface Verdict {
	block: boolean;
	/** a `data:` URL to answer with instead ($redirect) */
	redirect?: string;
	/** the URL to fetch instead ($removeparam) */
	url?: string;
}

/** a request as the service worker is about to send it, by its real URLs */
export interface BlockerRequest {
	/** the real URL */
	url: string;
	/** the real URL of the document or worker that makes it (a nested document's parent), or '' when nobody knows */
	source: string;
	/** the fetch event's destination (the load an inject's copy stands for) */
	destination: string;
	navigation: boolean;
	topLevel: boolean;
	method: string;
	/** a beacon or an `<a ping>` */
	ping?: boolean;
}

/** what the lists say of a request: at most one of the three */
export interface Decision {
	/** blocked: a network error to the page */
	block?: true;
	/** `$redirect`: answered with this resource instead of the network */
	resource?: { body: Uint8Array<ArrayBuffer>; type: string };
	/** `$removeparam`: fetched at this URL instead */
	url?: string;
}

/** the bytes and type of a `data:` URL as the crate writes a redirect resource (`data:<mime>;base64,<body>`) */
function dataResource(
	url: string,
): { body: Uint8Array<ArrayBuffer>; type: string } | null {
	const match = /^data:([^;,]*)((?:;[^;,]*)*),(.*)$/s.exec(url);
	if (!match) return null;
	try {
		const text = /;base64$/i.test(match[2])
			? atob(match[3])
			: decodeURIComponent(match[3]);
		return {
			body: Uint8Array.from(text, (char) => char.charCodeAt(0)),
			type: match[1] || 'text/plain',
		};
	} catch (error) {
		return null;
	}
}

/** what the crate answers for a document's cosmetic resources */
export interface CosmeticResources {
	hide_selectors: string[];
	procedural_actions: string[];
	exceptions: string[];
	injected_script: string;
	generichide: boolean;
}

/** a fetch through the transport (the lists come from their servers as the page's requests do) */
type FetchResource = (url: string) => Promise<Response>;

async function keyOf(init: AdblockInit): Promise<string> {
	const text = JSON.stringify([
		FORMAT,
		init.lists.map((list) => [
			list.url,
			!!list.trusted,
			list.format ?? '',
			// an inline list (the custom-filters editor) is its text, so two
			// different rule sets never share a stored engine
			list.filters ?? null,
		]),
		init.engine ?? '',
	]);
	const digest = await crypto.subtle.digest(
		'SHA-256',
		new TextEncoder().encode(text),
	);
	return Array.from(new Uint8Array(digest), (byte) =>
		byte.toString(16).padStart(2, '0'),
	).join('');
}

/**
 * What the request path asks of a blocker: the engine itself (Blocker), or,
 * for a slot of the site pool, the hub's worker's engine asked over a
 * port (src/server/remoteBlocker.ts), whose answers come later; the callers
 * await each one
 */
export interface BlockerLike {
	readonly ready: boolean;
	readonly failed: boolean;
	lastError: string | null;
	settled(build?: boolean, ms?: number): Promise<boolean>;
	decide(request: BlockerRequest): Decision | null | Promise<Decision | null>;
	socket(
		url: string,
		source: string,
		type?: 'webtransport',
	): boolean | Promise<boolean>;
	cosmetic(
		url: string,
		rewrite: (script: string) => string,
	): AdblockPage | null | Promise<AdblockPage | null>;
	documentCsp(
		url: string,
		top: string | null,
		sealer?: string,
	): string | null | Promise<string | null>;
	classIds(
		classes: string[],
		ids: string[],
		exceptions: string[],
	): string[] | Promise<string[]>;
}

/** the scriptlets of a document's cosmetic resources as one key (the crate writes them in any order) */
export function scriptletKey(script: string): string {
	return script.split('\n').sort().join('\n');
}

export class Blocker implements BlockerLike {
	#init: AdblockInit;
	readonly #fetch: FetchResource;
	readonly #given: () => Promise<WebAssembly.Module | null>;
	readonly #pool: () => RewritePool | undefined;
	#module: WebAssembly.Module | null = null;
	#instance: BlockerInstance | null = null;
	/** the engine is loaded and answers */
	#ready = false;
	/** the first load or build, whichever settles first; false when nothing could be loaded */
	readonly #settled: Promise<boolean>;
	/** the engine this browser stored was tried: it serves, or there is none and the lists are being fetched */
	readonly #restored: Promise<void>;
	#tried: () => void = () => {};
	#key = '';
	#resources = '';
	#building: Promise<void> | null = null;
	#replacing: Promise<void> | null = null;
	/**
	 * bumped whenever the lists change (`reconfigure`): a build that was fetching
	 * the old lists when the lists changed must not load its stale engine over
	 * the new one, so `#build` checks the generation it started in before it
	 * swaps or stores
	 */
	#generation = 0;
	readonly #scripts = new Map<string, string>();
	/** a host-visible note of what went wrong, for the request log */
	lastError: string | null = null;

	/** `module` settles with the thread's compiled blocker module, or null when it has none */
	constructor(
		init: AdblockInit,
		fetch: FetchResource,
		module: () => Promise<WebAssembly.Module | null>,
		/** the rewrite workers of the newest controller, which compile an engine off this thread */
		pool: () => RewritePool | undefined = () => undefined,
	) {
		this.#init = init;
		this.#fetch = fetch;
		this.#given = module;
		this.#pool = pool;
		this.#restored = new Promise((resolve) => {
			this.#tried = resolve;
		});
		this.#settled = this.#start();
		this.#settled.then((ready) => {
			this.#tried();
			this.#failed = !ready;
			// on by default and nothing to serve with: the proxy works
			// without it, and says so once
			if (!ready && init.byDefault && !saidOff) {
				saidOff = true;
				console.info(
					`Stomp: the content blocker is off: ${this.lastError ?? 'no engine could be loaded'}`,
				);
			}
		});
	}
	get ready(): boolean {
		return this.#ready;
	}
	#failed = false;
	/** the start is over and no engine answers: the next controller to ask gets a new blocker, which tries again */
	get failed(): boolean {
		return this.#failed && !this.#ready && !this.#building;
	}
	/**
	 * the engine answers, or nothing could be loaded; bounded by `ms` for a
	 * page that must not wait on a first fetch of the lists. Without `build`
	 * the wait is for the stored engine alone (milliseconds), never for the
	 * lists' servers: a blocker that is on by default delays no page
	 */
	settled(build = true, ms = FIRST_BUILD_WAIT_MS): Promise<boolean> {
		if (this.#ready) return Promise.resolve(true);
		if (!build) return this.#restored.then(() => this.#ready);
		return Promise.race([
			this.#settled,
			new Promise<boolean>((resolve) => setTimeout(() => resolve(false), ms)),
		]);
	}

	/**
	 * Change the lists this blocker serves at runtime (the demo's Filter Lists
	 * editor, docs/adblock.md "Changing the lists"). The engine now serving keeps
	 * answering requests until the new lists are compiled, then the new engine is
	 * swapped in in place: the Blocker object's identity never changes, so the
	 * request path that holds it needs no rewiring. A stored engine for the new
	 * lists loads in milliseconds; otherwise they are fetched and compiled in the
	 * background. `force` recompiles even when a fresh stored engine for these
	 * exact lists exists (the "Update lists" button re-fetches).
	 */
	async reconfigure(init: AdblockInit, force = false): Promise<void> {
		this.#init = init;
		// any build in flight is for the old lists now (its generation check
		// drops it); a fresh #refresh below reads the new #init
		this.#generation++;
		this.#building = null;
		this.#failed = false;
		if (!this.#module) {
			try {
				this.#module = await this.#given();
			} catch (error) {
				this.#module = null;
			}
			if (!this.#module) {
				this.lastError = 'the blocker module did not reach the service worker';
				return;
			}
		}
		try {
			this.#key = await keyOf(init);
		} catch (error) {
			this.#key = '';
		}
		const stored = !force && this.#key ? await this.#stored() : null;
		if (stored && this.#load(stored.engine, stored.resources)) {
			this.#scripts.clear();
			if (Date.now() - stored.at > init.refreshMs) void this.#refresh();
			return;
		}
		await this.#refresh();
	}

	async #start(): Promise<boolean> {
		try {
			this.#module = await this.#given();
		} catch (error) {
			this.#module = null;
		}
		if (!this.#module) {
			this.lastError = 'the blocker module did not reach the service worker';
			return false;
		}
		try {
			this.#key = await keyOf(this.#init);
		} catch (error) {
			// no crypto.subtle (an insecure context): the engine is built every start
			this.#key = '';
		}
		const stored = this.#key ? await this.#stored() : null;
		if (stored) {
			const loaded = this.#load(stored.engine, stored.resources);
			const stale = Date.now() - stored.at > this.#init.refreshMs;
			if (loaded && !stale) return true;
			if (loaded) {
				// serve the stored engine while a fresh one is fetched
				this.#refresh(true);
				return true;
			}
		}
		this.#tried();
		await this.#refresh(!!this.#init.byDefault);
		return this.#ready;
	}

	/** the stored engine and resources under this key, when both are there */
	async #stored(): Promise<{
		engine: Uint8Array<ArrayBuffer>;
		resources: string;
		at: number;
	} | null> {
		try {
			const cache = await caches.open(STORE);
			const engine = await cache.match(this.#url('engine'));
			const resources = await cache.match(this.#url('resources'));
			if (!engine || !resources) return null;
			return {
				engine: new Uint8Array(await engine.arrayBuffer()),
				resources: await resources.text(),
				at: Number(engine.headers.get(STORED_AT)) || 0,
			};
		} catch (error) {
			return null;
		}
	}
	#url(part: string): string {
		return `https://adblock.stomp.invalid/${this.#key}/${part}`;
	}
	async #store(
		engine: Uint8Array<ArrayBuffer>,
		resources: string,
	): Promise<void> {
		if (!this.#key) return;
		try {
			const cache = await caches.open(STORE);
			// everything under other keys is an engine of other lists or an
			// older format: dropped, so the store holds one engine
			for (const request of await cache.keys())
				if (
					!request.url.startsWith(`https://adblock.stomp.invalid/${this.#key}/`)
				)
					await cache.delete(request);
			const headers = { [STORED_AT]: String(Date.now()) };
			await cache.put(this.#url('engine'), new Response(engine, { headers }));
			await cache.put(
				this.#url('resources'),
				new Response(resources, { headers }),
			);
		} catch (error) {
			// no storage: the engine is built again next start
		}
	}

	/** a fresh instance holding `engine` and `resources`; false when the bytes are not an engine of this format */
	#load(engine: Uint8Array<ArrayBuffer>, resources: string): boolean {
		let instance: BlockerInstance;
		try {
			instance = new BlockerInstance(this.#module!);
			if (instance.call(resources, OP.resources) !== 0) return false;
			if (instance.call(engine, OP.load) !== 0) return false;
		} catch (error) {
			this.lastError = `the engine could not be loaded: ${String(error)}`;
			return false;
		}
		this.#instance = instance;
		this.#resources = resources;
		this.#ready = true;
		setTimeout(() => this.#warm(instance), 0);
		return true;
	}
	/**
	 * Ask a fresh instance what a page's first loads ask, about an address
	 * no list names, once the worker has nothing else to do: the first
	 * questions an instance is asked compile the parts of the module that
	 * answer them, 5 to 7 ms each of the first navigation's and its first
	 * subresources' time otherwise. The answers are dropped; asking changes
	 * nothing an engine answers later.
	 */
	#warm(instance: BlockerInstance) {
		if (this.#instance !== instance) return;
		const page = 'https://warm.stomp.invalid/';
		const other = 'https://other.stomp.invalid/a.js';
		try {
			for (const type of [
				'document',
				'subdocument',
				'script',
				'stylesheet',
				'image',
				'font',
				'xmlhttprequest',
				'media',
				'other',
			])
				instance.call(
					`${type === 'document' ? page : other}\t${page}\t${type}\tget`,
					OP.check,
				);
			instance.call(`${page}\t${page}\tdocument\tget`, OP.csp);
			instance.call(page, OP.cosmetic);
		} catch (error) {
			// a trap: the instance is replaced the first time a page asks it
		}
	}

	/**
	 * fetch the lists and the resources, build, store and swap in the engine;
	 * with `turn` (a start's: a stored engine serves meanwhile, or the blocker
	 * is on by default and no navigation waits for it) the downloads wait for
	 * the worker's first navigation to go first (listTurn)
	 */
	#refresh(turn = false): Promise<void> {
		if (!this.#building)
			this.#building = this.#build(turn).finally(() => {
				this.#building = null;
			});
		return this.#building;
	}
	async #build(turn: boolean): Promise<void> {
		// the lists in force when this build began: if `reconfigure` changes them
		// while this build is fetching, its engine is stale and must be discarded
		// rather than loaded over the newer lists (see #generation)
		const generation = this.#generation;
		if (turn) await listTurn();
		if (generation !== this.#generation) return;
		// the resources (Brave's resources.json) are needed to load the engine,
		// not to compile it, so fetch them alongside the lists (or the prebuilt
		// engine) rather than before: their round trip then overlaps the list
		// fetch and the compile instead of adding a serial fetch to every cold
		// build. The list fetch failing must not leave this rejection unhandled
		const resourcesPromise = (async () => {
			const text = await this.#fetchText(this.#init.resources);
			JSON.parse(text);
			return text;
		})();
		resourcesPromise.catch(() => {});
		let engine: Uint8Array<ArrayBuffer>;
		/** the lists compiled into `engine`, when it was not prebuilt */
		let entries: EngineList[] | undefined;
		if (this.#init.engine) {
			try {
				engine = new Uint8Array(
					await (await this.#fetchOk(this.#init.engine)).arrayBuffer(),
				);
			} catch (error) {
				this.lastError = `the prebuilt engine could not be fetched: ${String(error)}`;
				return;
			}
		} else {
			let missed = '';
			// the first list of each host opens its connection, and the others
			// of that host go once it has answered, over it: asked together,
			// each opened a connection of its own, so the wisp server looked
			// the host up once for each (two to four times for the default
			// lists' two hosts), on the threads a page's lookups wait for
			const opened = new Map<string, Promise<unknown>>();
			const lists = await Promise.all(
				this.#init.lists.map(async (list) => {
					// an inline list (the custom-filters editor) is its own text:
					// compiled in place, never fetched (docs/adblock.md)
					if (list.filters !== undefined) return { list, text: list.filters };
					try {
						const host = listHost(list.url);
						const first = opened.get(host);
						const response = first
							? first.then(() => this.#fetchOk(list.url))
							: this.#fetchOk(list.url);
						if (!first)
							opened.set(
								host,
								response.catch(() => {}),
							);
						return { list, text: await (await response).text() };
					} catch (error) {
						missed ||= String(error);
						// a list the host named is the host's to hear of; one of
						// the default lists is left out quietly (with none at all
						// the blocker says once that it is off)
						if (!this.#init.byDefault)
							console.warn(`Stomp: filter list not fetched: ${String(error)}`);
						return null;
					}
				}),
			);
			const fetched = lists.filter(
				(entry): entry is { list: AdblockList; text: string } => entry !== null,
			);
			if (!fetched.length) {
				this.lastError = `no filter list could be fetched (${missed})`;
				return;
			}
			entries = fetched.map(({ list, text }) => ({
				text,
				flags:
					(list.trusted ? FLAG_TRUSTED : 0) |
					(list.format === 'hosts' ? FLAG_HOSTS : 0),
			}));
			// a rewrite worker's thread compiles it when the controller has
			// one (src/blocker/build.ts), this thread otherwise
			const built =
				(await this.#buildElsewhere(entries)) ?? this.#buildHere(entries);
			if (!built) return;
			engine = built;
		}
		let resources: string;
		try {
			resources = await resourcesPromise;
		} catch (error) {
			// the lists still block and hide without them; only the scriptlets
			// and the `$redirect` answers are missing (a host that does not
			// serve the directory's adblock-resources.json). Nothing is stored,
			// so the next worker tries them again
			resources = '';
			(this.#init.byDefault ? console.info : console.warn)(
				`Stomp: the content blocker runs without scriptlets: the resources could not be fetched: ${String(error)}`,
			);
		}
		// the lists changed under this build (reconfigure): its engine is for
		// the old lists, so drop it rather than serve or store it
		if (generation !== this.#generation) return;
		// the engine is loaded into an instance of its own (the builder holds
		// the lists' text and the build's garbage), stored, and serves. One a
		// worker compiled that this thread's module cannot load (a module of
		// another handshake's build) is compiled here instead
		let loaded = this.#load(engine, resources || '[]');
		if (!loaded && entries && this.#builtElsewhere === engine) {
			const built = this.#buildHere(entries);
			if (built) loaded = this.#load((engine = built), resources || '[]');
		}
		if (loaded) {
			this.#scripts.clear();
			if (resources) await this.#store(engine, resources);
		}
	}
	/** the engine a rewrite worker compiled from `lists`, null when none could */
	#builtElsewhere: Uint8Array<ArrayBuffer> | null = null;
	async #buildElsewhere(
		lists: EngineList[],
	): Promise<Uint8Array<ArrayBuffer> | null> {
		const pool = this.#pool();
		if (!pool?.live || !moduleBytes) return null;
		try {
			this.#builtElsewhere = await pool.buildEngine({
				module: moduleBytes,
				lists,
			});
		} catch (error) {
			this.#builtElsewhere = null;
		}
		return this.#builtElsewhere;
	}
	/** the engine of `lists` compiled on this thread (one call of 220 to 280 ms for the default lists) */
	#buildHere(lists: EngineList[]): Uint8Array<ArrayBuffer> | null {
		try {
			const builder = new BlockerInstance(this.#module!);
			for (const { text, flags } of lists)
				builder.call(text, OP.addList | flags);
			if (builder.call('', OP.build) !== 0) {
				this.lastError = 'the lists could not be compiled';
				return null;
			}
			return builder.bytes();
		} catch (error) {
			this.lastError = `the lists could not be compiled: ${String(error)}`;
			return null;
		}
	}
	async #fetchOk(url: string): Promise<Response> {
		// a file of STomp's own origin (the default resources, which the
		// directory serves beside blocker.wasm) is the worker's to read: the
		// transport would ask the wisp server for this origin
		const own = globalThis.location?.origin;
		const response =
			own && new URL(url, own).origin === own
				? await fetch(url)
				: await this.#fetch(url);
		if (!response.ok) throw new Error(`status ${response.status} for ${url}`);
		return response;
	}
	async #fetchText(url: string): Promise<string> {
		return (await this.#fetchOk(url)).text();
	}

	/** the instance to ask, replaced when it has grown past the ceiling */
	#engine(): BlockerInstance | null {
		const instance = this.#instance;
		if (!instance) return null;
		if (instance.memoryBytes > MEMORY_LIMIT && !this.#replacing)
			this.#replacing = this.#replace().finally(() => {
				this.#replacing = null;
			});
		return instance;
	}
	async #replace(): Promise<void> {
		const stored = await this.#stored();
		if (stored) this.#load(stored.engine, stored.resources);
	}
	#call(input: string, op: number): string | null {
		const instance = this.#engine();
		if (!instance) return null;
		try {
			if (instance.call(input, op) !== 0) return null;
			return instance.text();
		} catch (error) {
			// a trap: the instance is dead, a fresh one loads the stored engine
			this.#instance = null;
			this.#ready = false;
			if (!this.#replacing)
				this.#replacing = this.#replace().finally(() => {
					this.#replacing = null;
				});
			return null;
		}
	}

	/** the lists' verdict on a request, or null while no engine answers */
	check(
		url: string,
		source: string,
		type: string,
		method: string,
	): Verdict | null {
		const answer = this.#call(
			`${url}\t${source}\t${type}\t${method.toLowerCase()}`,
			OP.check,
		);
		if (answer === null) return null;
		try {
			const parsed = JSON.parse(answer) as {
				block?: boolean;
				redirect?: string;
				url?: string;
			};
			return { block: !!parsed.block, ...parsed };
		} catch (error) {
			return null;
		}
	}
	/** the `$csp=` directives for a document or subdocument, joined, or null */
	csp(url: string, source: string, type: string): string | null {
		const answer = this.#call(`${url}\t${source}\t${type}\tget`, OP.csp);
		return answer || null;
	}
	/**
	 * the cosmetic side of the lists for a document at `url`: what the inject
	 * applies, with the scriptlets rewritten by `rewrite` (a page's script)
	 */
	cosmetic(
		url: string,
		rewrite: (script: string) => string,
	): AdblockPage | null {
		const resources = this.cosmeticResources(url);
		if (resources === null) return null;
		let script = '';
		if (resources.injected_script) {
			// the crate writes a page's scriptlets in the order of a hash set
			// that changes from call to call: the same lines in any order are
			// the same scriptlets, and one rewrite serves them all
			const key = scriptletKey(resources.injected_script);
			const memo = this.#scripts.get(key);
			if (memo !== undefined) script = memo;
			else {
				try {
					// uBlock Origin's scriptlets read `scriptletGlobals`, which the
					// blocker that runs them declares around them (uBO's own
					// scriptlet template, Brave's injection): without it the first
					// scriptlet's first safeSelf() throws and that scriptlet is lost
					script = rewrite(
						`const scriptletGlobals = {};\n${resources.injected_script}`,
					);
				} catch (error) {
					console.warn('Stomp: the scriptlets could not be rewritten', error);
					script = '';
				}
				if (this.#scripts.size >= SCRIPT_MEMO)
					this.#scripts.delete(this.#scripts.keys().next().value!);
				this.#scripts.set(key, script);
			}
		}
		return {
			hide: resources.hide_selectors,
			procedural: resources.procedural_actions,
			exceptions: resources.exceptions,
			script,
			generichide: resources.generichide,
		};
	}
	/** the crate's cosmetic resources for a document at `url`, its scriptlets as the lists have them */
	cosmeticResources(url: string): CosmeticResources | null {
		const answer = this.#call(url, OP.cosmetic);
		if (answer === null) return null;
		try {
			return JSON.parse(answer) as CosmeticResources;
		} catch (error) {
			return null;
		}
	}
	/** the generic hide selectors among `classes` and `ids` a page saw, minus its `exceptions` */
	classIds(classes: string[], ids: string[], exceptions: string[]): string[] {
		const answer = this.#call(
			JSON.stringify({ classes, ids, exceptions }),
			OP.classIds,
		);
		if (answer === null) return [];
		try {
			return JSON.parse(answer) as string[];
		} catch (error) {
			return [];
		}
	}
	/**
	 * What the lists say of a request, or null for "send it": the request's
	 * type as a content blocker in the browser would name it, and its party
	 * from the real document that makes it
	 */
	decide(request: BlockerRequest): Decision | null {
		const type = request.ping
			? 'ping'
			: requestTypeOf(
					request.destination,
					request.navigation,
					request.topLevel,
				);
		const verdict = this.check(
			request.url,
			// a top-level document is its own first party
			request.navigation && request.topLevel ? request.url : request.source,
			type,
			request.method,
		);
		if (!verdict) return null;
		if (verdict.redirect) {
			const resource = dataResource(verdict.redirect);
			if (resource) return { resource };
		}
		if (verdict.block) return { block: true };
		if (verdict.url && verdict.url !== request.url) return { url: verdict.url };
		return null;
	}
	/**
	 * Whether the lists block a WebSocket to `url` (ws: or wss:) opened under
	 * `source`. A `$redirect` or `$removeparam` rule that matches a socket
	 * has nothing to answer with or to rewrite: a redirect rule blocks, as in
	 * uBlock Origin, and the other is not applied. False while no engine
	 * answers, as for any request that is not a navigation.
	 */
	socket(url: string, source: string, type?: 'webtransport'): boolean {
		// a WebTransport session: adblock-rust has no type of its own for it
		// (Chrome's blocker has `webtransport`), so only the rules that name
		// no type apply to it, as they do in Chrome's
		return !!this.check(
			url,
			source,
			type ? 'other' : 'websocket',
			type ? 'CONNECT' : 'GET',
		)?.block;
	}
	/**
	 * The `$csp=` policies of the lists for a document at `url` (a nested
	 * one's `top` is the page it is framed under), reduced to what the proxy
	 * can enforce (src/blocker/csp.ts), or null
	 */
	documentCsp(
		url: string,
		top: string | null,
		/** the URL of the sealed copies' worker, which every carried policy lets run */
		sealer?: string,
	): string | null {
		const directives = this.csp(
			url,
			top ?? url,
			top === null ? 'document' : 'subdocument',
		);
		const carried = directives ? carriedCsp(directives) : null;
		return carried && sealer ? withWorkerSource(carried, sealer) : carried;
	}
	/** the resources JSON the engine holds (tests) */
	get resourcesText(): string {
		return this.#resources;
	}
}

/**
 * The route a document's inject asks for the generic hide rules of the
 * classes and ids it has seen (docs/adblock.md): `{classes, ids,
 * exceptions}` in, the selectors to hide out. Under the controller's
 * address, like `whoami`: no page URL corresponds to it.
 */
export function registerBlocker(router: Router, blocker: BlockerLike) {
	router.routes.set(/^\/adblock$/, async (request) => {
		let selectors: string[] = [];
		try {
			const asked = (await request.json()) as {
				classes?: unknown;
				ids?: unknown;
				exceptions?: unknown;
			};
			const strings = (value: unknown): string[] =>
				Array.isArray(value)
					? value.filter((entry): entry is string => typeof entry === 'string')
					: [];
			selectors = await blocker.classIds(
				strings(asked.classes),
				strings(asked.ids),
				strings(asked.exceptions),
			);
		} catch (error) {
			// not a question: no rules
		}
		return new Response(JSON.stringify(selectors), {
			headers: {
				'content-type': 'application/json',
				'cache-control': 'no-store',
			},
		});
	});
}
